evals.prompt:
We have no documentation for the boiler feedwater pump lead/lag logic in an old PLC at a district heating plant. Here is the structured text extracted from the program. Write the FRS section that describes what it does, so we can re-implement it on the new platform.

---
// FW pumps P1,P2. LT100 drum level %, PT101 FW header bar
IF LeadSel = 1 THEN Lead := P1; Lag := P2; ELSE Lead := P2; Lag := P1; END_IF;
IF AutoMode AND NOT Lead.Fault THEN Lead.Run := TRUE; END_IF;
IF PT101 < 18.5 THEN LagTmr(IN:=TRUE, PT:=T#8s); ELSE LagTmr(IN:=FALSE); END_IF;
IF LagTmr.Q OR Lead.Fault THEN Lag.Run := TRUE; LagLatched := TRUE; END_IF;
IF PT101 > 21.0 AND LagLatched THEN Lag.Run := FALSE; END_IF;
IF LT100 < 15.0 THEN P1.Run := FALSE; P2.Run := FALSE; END_IF; // protect pumps
IF Maint_B7 THEN LT100_Lo := FALSE; END_IF;
IF DayOfWeek = 1 AND Hour = 6 AND Minute = 0 THEN LeadSel := NOT LeadSel; END_IF;
---
